"aef-villars":{"rev":"b19f5de8e06228cb3ea428e47c6ce1638efd0c4cd2eaf5db3108136c0f55640f","strings":{"name":"Café parents-enfants · Villars-Vert","parentDetails":"Les parents et adultes accompagnants jouent avec les enfants au café, en présence d’une personne de l’équipe d’Éducation Familiale ; la page n’indique pas si la présence pendant toute la séance est obligatoire.","age":"L’âge pour le café du vendredi n’est pas précisé","schedule":"ven. 09:00–11:00 · dates publiées jusqu’au 18.12.2026","price":"Prix non publié","address":"Route de Villars-Vert 26, 1752 Villars-sur-Glâne","notes[0]":"Une rencontre de jeu pour un enfant avec un adulte, et une discussion entre parents et une personne de l’équipe d’Éducation Familiale.","notes[1]":"Le prix, l’inscription, la langue et d’éventuelles limites d’âge propres à la rencontre du vendredi ne sont pas précisés dans le programme actuel. À ne pas confondre avec le groupe Tilou gratuit du lundi, distinct, dans les mêmes locaux.","notes[2]":"Seules les dates publiées par l’AEF sont indiquées ici ; les vacances scolaires sont exclues.","practical.indoor.text":"La rencontre a lieu à l’intérieur, au Le Milieu.","research.findings[0].field":"Rencontres publiées","research.findings[0].text":"Le calendrier de l’AEF indique des rencontres le vendredi de 09:00 à 11:00 au Le Milieu jusqu’au 18 décembre 2026. Il y a une pause en octobre.","research.findings[1].field":"Lieu et format","research.findings[1].text":"La commune décrit le café du vendredi de l’AEF comme des enfants qui jouent avec des adultes et une discussion avec une personne de l’équipe d’Éducation Familiale, à la Route de Villars-Vert 26.","research.findings[2].field":"Lieu et format","research.findings[2].text":"La page de la commune décrit le café du vendredi comme un espace de jeu entre les enfants et leurs parents ou adultes accompagnants, avec une personne de l’équipe d’Éducation Familiale présente, au centre d’animation Le Milieu, Route de Villars-Vert 26.","research.findings[3].field":"Dates publiées","research.findings[3].text":"La page de la commune indique le café du vendredi chaque vendredi de 9:00 à 11:00 du 8 septembre au 22 décembre, sauf les 20 et 27 octobre et le 8 décembre, sans mentionner d’année. Les dates de 2026 ne sont donc pas confirmées par cette page.","research.findings[4].field":"Adresse du lieu","research.findings[4].text":"La page de la commune indique comme lieu du café du vendredi le centre d’animation Le Milieu, Route de Villars-Vert 26.","research.remaining[0]":"Pour le café du vendredi, les limites d’âge, le coût, l’inscription et la langue doivent être vérifiés séparément ; les conditions du groupe Tilou du lundi ne s’appliquent pas forcément.","research.remaining[1]":"Quels vendredis d’automne 2026 le café a-t-il lieu ? La page de la commune indique des dates sans année et exclut les 20 et 27 octobre.","research.remaining[2]":"Le café a-t-il lieu à l’intérieur ? La page de la commune nomme le centre mais ne le précise pas.","contacts[0].name":"Éducation Familiale : FR 026 321 48 70 ; DE 026 322 86 33","sources[0].label":"AEF : rencontres d’automne et adresse","sources[1].label":"Commune : format avec un parent et adresse"}},
"aerodrome-epagny-play":{"rev":"19c0301cffc6ef5fd75345073308e89ac46ea32eddb773ad1e1b4793fd150094","strings":{"name":"Restaurant de l’aérodrome · espace de jeu","intro":"Un restaurant près de l’aérodrome avec un grand espace de jeu et une terrasse.","age":"Les limites d’âge ne sont pas publiées.","schedule":"mer.–jeu. 09:00–22:00 ; ven. 09:00–23:00 ; sam. 08:30–23:00 ; dim. 08:30–22:00","price":"Le prix n’est pas publié.","address":"Route de l’Aérodrome 40, 1663 Epagny","notes[0]":"Vous pouvez observer l’aérodrome, mais la page ne promet ni activité aérienne ni la sécurité de la zone d’observation.","notes[1]":"Les heures d’ouverture du restaurant sont publiées pour 2026. L’espace de jeu peut être indisponible lors d’un événement privé.","practical.indoor.text":"Le restaurant de l’aérodrome indique un grand espace de jeu et une terrasse.","practical.warnings[0]":"L’âge des équipements, les prix et la disponibilité de l’espace de jeu sans commande ne sont pas décrits.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"Le restaurant de l’aérodrome indique un grand espace de jeu et une terrasse.","research.findings[1].field":"Heures d’ouverture","research.findings[1].text":"Les heures publiées du restaurant pour 2026 sont : fermé le lundi et le mardi ; mercredi–jeudi 09:00–22:00 ; vendredi 09:00–23:00 ; samedi 08:30–23:00 ; dimanche 08:30–22:00. Ce sont les heures du restaurant, pas des heures spécifiques à l’espace de jeu.","research.remaining[0]":"L’âge des équipements, les prix et la disponibilité de l’espace de jeu sans commande ne sont pas décrits.","contacts[0].name":"Café-Restaurant de l’Aérodrome","sources[0].label":"Grand espace de jeu, terrasse et heures d’ouverture"}},
