"biblio-marly":{"rev":"a796b7af0c56f70b5139b75e12b2bcab68fa8296e8e9db4f31cd45835a171569","strings":{"name":"Bibliothèque régionale de Marly","age":"Visite en famille","schedule":"Horaires de la bibliothèque : mar., mer., ven. 14:00–18:00 · jeu., sam. 09:00–12:00 ; fermé le lundi. Heure du conte (L'heure du conte), dès 4 ans : les mercredis 14:00–14:45, uniquement aux dates publiées (11 nov. et 9 déc. 2026 ; 13 janv., 17 févr., 10 mars, 14 avr. et 12 mai 2027).","price":"Prix non publié","address":"Route de Fribourg 15, Marly","notes[0]":"La langue de la personne ou du service d’accueil n’est pas confirmée.","notes[1]":"Les heures d’ouverture de la bibliothèque ne sont pas les mêmes que les horaires de Né pour lire.","research.findings[0].field":"Horaires et visites","research.findings[0].text":"Le registre cantonal indique mar., mer., ven. 14:00–18:00 et jeu., sam. 09:00–12:00, avec la mention « Sur rendez-vous » au-dessus des horaires, qu’il n’explique pas. La page de la bibliothèque sur le site de la commune donne les mêmes horaires et indique que le lundi est fermé. Aucune source vérifiée n’indique qu’une visite ordinaire nécessite un rendez-vous.","research.remaining[0]":"Une visite ordinaire nécessite-t-elle un rendez-vous, vu la mention « Sur rendez-vous » dans le registre cantonal ?","research.remaining[1]":"Quel est le montant de la cotisation à la bibliothèque, s’il y en a une ?","research.remaining[2]":"Y a-t-il en 2026 des fermetures de la bibliothèque qui touchent les horaires habituels ?","contacts[0].name":"Bibliothèque","sources[0].label":"Registre cantonal des bibliothèques"}},
"biblio-tafers":{"rev":"01a4dbc7bbd2313182e4495130bba7d463bc068950ca451ceeec6919d5f2e9a6","strings":{"name":"Bibliothek Tafers","age":"Visite en famille","schedule":"lun., mar. 15:00–17:00 · mer., sam. 09:30–11:30 · jeu. 15:00–17:00 et 18:00–19:30. Pendant les vacances scolaires : jeu. 18:00–19:30 et sam. 09:30–11:30","price":"Selon l’annuaire 2025/26 : gratuit pour les enfants, CHF 40 / an pour les adultes ; nouveau tarif à confirmer","address":"Juchstrasse 9, OS, Tafers","notes[0]":"La langue de la personne hôte ou du service n’est pas confirmée","research.findings[0].field":"Horaires","research.findings[0].text":"Le registre cantonal des bibliothèques indique les horaires d’ouverture suivants : lun. et mar. 15:00–17:00, mer. 09:30–11:30, jeu. 15:00–17:00 et 18:00–19:30, et sam. 09:30–11:30. Pendant les vacances scolaires, il indique jeu. 18:00–19:30 et sam. 09:30–11:30. Le registre précise que la bibliothèque est ouverte toute l’année avec des horaires adaptés.","research.findings[1].field":"Contacts","research.findings[1].text":"Le registre cantonal des bibliothèques indique comme numéro de téléphone de la bibliothèque le +41 26 494 52 55 et comme adresse e-mail info@bibliothek-tafers.ch.","research.remaining[0]":"Le tarif de CHF 40 provient de l’annuaire 2025/26 précédent ; confirmer le tarif actuel et les conditions de l’abonnement des enfants.","research.remaining[1]":"Les horaires du site web de la bibliothèque diffèrent-ils de ceux du registre cantonal, par exemple le jeudi après-midi ?","contacts[0].name":"Bibliothek Tafers","sources[0].label":"Source officielle","sources[1].label":"Registre cantonal des bibliothèques","sources[2].label":"Vérification complémentaire : nouveaux horaires"}},
"billens-kids-natation":{"rev":"0f8cc02770ba9ee373c75f8b41942c277b80570f2ae0d0cb671dd1426d54e578","strings":{"name":"Kids Natation · dans l’eau avec un parent","intro":"L’opérateur confirme des séances de Motricité parent-enfant pour les enfants d’environ 1 à 3 ou 4 ans, CHF 23 pour 15 minutes et un bloc d’essai de trois séances pour CHF 50.","parentDetails":"Un adulte participe au cours dans l’eau avec l’enfant et est responsable de l’enfant dans l’eau comme en dehors.","age":"Groupe Motricité, de 12 mois à 3 ou 4 ans","schedule":"Chaque semaine, hors vacances scolaires ; le jour et l’heure précis sont à confirmer.","price":"CHF 23 par séance de Motricité (15 minutes), entrée de l’adulte et de l’enfant comprise ; 3 séances d’essai CHF 50.","address":"Piscine HFR Billens, Route de l’Hôpital 1, 1681 Billens-Hennens","notes[0]":"Le site web mentionne un certificat du pédiatre à l’inscription et un renouvellement automatique pour chaque période : réglez à l’avance toute résiliation avec l’opérateur.","notes[1]":"Il s’agit d’un prestataire distinct d’Aquaçasert à la même piscine. Les tarifs ne sont pas interchangeables.","practical.indoor.text":"À confirmer","practical.commitment.text":"Les cours sont facturés par période, payables à l’avance et non remboursables.","practical.trial.text":"Trois cours d’essai sont proposés pour CHF 50, payables à l’avance.","practical.warnings[0]":"Les places libres, l’horaire 2026/27, la langue de la personne qui enseigne et la nécessité d’un certificat médical dans un cas précis sont à confirmer.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"L’opérateur confirme des séances de Motricité parent-enfant pour les enfants d’environ 1 à 3 ou 4 ans, CHF 23 pour 15 minutes et un bloc d’essai de trois séances pour CHF 50.","research.findings[1].field":"Inscription et tarif","research.findings[1].text":"Les cours peuvent être commencés à tout moment de l’année. Le tarif comprend le cours et l’entrée à la piscine pour un enfant et un adulte.","research.remaining[0]":"Les places libres, l’horaire 2026/27, la langue de la personne qui enseigne et la nécessité d’un certificat médical dans un cas précis sont à confirmer.","research.remaining[1]":"Quel jour de la semaine et à quelle heure le groupe Motricité se réunit-il ?","research.remaining[2]":"Dans quelle langue les séances sont-elles données ?","research.remaining[3]":"L’espace piscine de ce cours est-il à l’intérieur ?","research.remaining[4]":"Combien d’enfants compte un groupe ?","contacts[0].name":"Kids Natation","sources[0].label":"Opérateur : âge, parent, prix et bloc d’essai","sources[1].label":"Opérateur : adresse de la piscine et contact"}},
