"espace-famille-bulle":{"rev":"379658d0be31530e82e1b980d10cca9bcf501cc9c5bfb375fe443dfb6e46be63","strings":{"name":"Espace Famille · jeu libre","intro":"Une salle de jeux pour les enfants avant l’âge scolaire et les adultes qui leur sont proches.","parentDetails":"L’enfant reste avec son adulte accompagnant pendant toute la durée. Ce n’est pas une garde d’enfants ni une crèche.","age":"0–5 ans, jusqu’à l’entrée à l’école (1H)","schedule":"lun., jeu. 14:00–17:30 ; mar., ven., sam. 09:00–11:30","price":"Don libre","address":"Rue de Vevey 260, 1630 Bulle","notes[0]":"Jeu libre en intérieur, sans inscription. Le site mentionne séparément une petite cuisine pour les collations.","notes[1]":"Les horaires peuvent changer pendant les vacances scolaires. L’adresse de visite indiquée sur le site est Rue de Vevey 260 ; l’adresse postale est Route de la Pâla 137a. Le calendrier de l’AEF indique une rencontre séparée à l’Espace Famille, à la Route de la Pâla 137 ; le lieu de cette rencontre doit être vérifié.","notes[2]":"La langue parlée par le personnel n’est pas indiquée. Le texte français du site ne confirme pas la langue de la rencontre.","practical.indoor.text":"Jeu libre en intérieur","practical.booking.text":"Sans inscription","practical.observe.text":"Vous pouvez d’abord observer en restant à côté de l’enfant","practical.commitment.text":"Don libre, pas d’abonnement","practical.leave.text":"Plage de visite ouverte","research.findings[0].field":"Première visite","research.findings[0].text":"Jeu libre pour les 0–5 ans avec un adulte, sans inscription, don libre. Le site indique des adresses de visite et postale différentes.","research.remaining[0]":"Vérifiez la langue du personnel qui accueille les visiteurs et les éventuels changements d’horaires pendant les vacances.","contacts[0].name":"Espace Famille","sources[0].label":"Format, horaires, don et adresse"}},
"espace-marly":{"rev":"863c1c5d42c4211fe7c1e294f4d022443cad7cdef56e5646cf5f41a4a8b74e96","strings":{"name":"Espace des familles","intro":"Espace de jeu pour les familles avec de jeunes enfants. Certains ateliers ont leurs propres horaires et conditions.","parentDetails":"Les parents participent avec leurs enfants, pour jouer ensemble, rencontrer d’autres parents et échanger. La page n’indique pas si un enfant peut participer sans adulte.","age":"0–4 ans","schedule":"1er et 3e vendredis · 09:30–11:30 et 13:30–15:30","price":"Gratuit","address":"Maison de quartier, Route des Écoles 32, Marly","notes[0]":"La langue parlée sur place n’est pas confirmée","notes[1]":"Annoncé en août 2026. Formulation : « pour les familles de Marly » ; participation des habitants d’autres communes à confirmer.","notes[2]":"Sans inscription. Certains ateliers ont une heure de début fixe.","practical.indoor.text":"Maison de Quartier","practical.booking.text":"Accueil libre sans inscription ; vérifiez chaque atelier séparément","practical.commitment.text":"Gratuit","practical.leave.text":"Pendant l’accueil libre, vous pouvez arriver et partir librement ; cela ne vaut pas automatiquement pour les ateliers","practical.warnings[0]":"Offre pour les familles de Marly : vérifiez l’admission des habitants d’une autre commune","research.findings[0].field":"Participation","research.findings[0].text":"Vous pouvez arriver et partir pendant les heures d’ouverture ; certains ateliers commencent à une heure fixe. La participation est gratuite, sans inscription. L’organisateur indique explicitement « pour les familles de Marly » ; l’accès pour les habitants d’une autre commune reste donc une question ouverte.","research.findings[1].field":"Ateliers","research.findings[1].text":"Des spécialistes invités peuvent proposer occasionnellement un atelier, un échange ou une présence professionnelle active sur des thèmes de la petite enfance et de la parentalité. La page lisible ne donne pas de dates d’ateliers.","research.remaining[0]":"Confirmer la participation des familles d’autres communes, la langue et l’ouverture pendant les vacances.","research.remaining[1]":"Existe-t-il des dates et des heures d’ateliers pour le programme d’automne ?","contacts[0].name":"Marly pour tous","sources[0].label":"Source officielle"}},
