"villorsonnens-forest-cabin-play":{"rev":"6132594edbb0b22628c0c229668193f9e7d66deeb5867cc43d8890396e87f4eb","strings":{"name":"Cabane de Villagiroud · place de jeux au bord de la forêt","intro":"La commune confirme une place de jeux pour enfants à côté de la cabane forestière et un grand parking.","age":"Les limites d’âge ne sont pas publiées","schedule":"L’accès à la place de jeux en dehors de la location de la cabane n’est pas précisé","price":"Le prix d’entrée à la place de jeux n’est pas publié. Location de la cabane uniquement (pas un tarif de la place de jeux) : CHF 100.00 par jour pour les personnes domiciliées à Villorsonnens, CHF 200.00 par jour pour les personnes de l’extérieur.","address":"Cabane forestière de Villagiroud, 1694 Villargiroud","notes[0]":"La cabane est fermée en hiver, du 15 octobre au 15 avril.","notes[1]":"La page de la commune indique que la cabane n’est pas accessible aux personnes à mobilité réduite ; l’accès en poussette n’est pas indiqué.","notes[2]":"Une rénovation de la cabane est prévue en 2028.","notes[3]":"La location de la cabane coûte CHF 100.00 par jour pour les personnes domiciliées et CHF 200.00 par jour pour les autres ; ce n’est pas le prix d’accès à la place de jeux.","practical.indoor.text":"La page de la commune n’indique pas si la place de jeux est à l’intérieur ou à l’extérieur.","practical.playArea.text":"La page de la commune mentionne une place de jeux à la cabane forestière.","practical.parking.text":"La page de la commune mentionne un grand parking à la cabane forestière ; elle n’indique pas si le parking est payant.","practical.costNote.text":"Tarif de location de toute la cabane, par jour, avec des tarifs distincts pour les personnes domiciliées et les personnes de l’extérieur ; tarif distinct pour l’espace de jeu : pas publié","practical.warnings[0]":"Il n’est pas indiqué si la place de jeux peut être utilisée sans louer la cabane ; l’interdiction hivernale concerne la cabane, et les règles pour la place de jeux ne sont pas définies.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"La commune confirme une place de jeux pour enfants à côté de la cabane forestière et un grand parking.","research.findings[1].field":"Statut","research.findings[1].text":"La page de la commune indique que la cabane forestière est fermée en hiver, du 15 octobre au 15 avril, donc hors saison le 31 octobre 2026. La page n’indique pas si la place de jeux elle-même est fermée.","research.findings[2].field":"Prix","research.findings[2].text":"La commune publie le tarif de location de la cabane forestière par jour : CHF 100.00 pour les personnes domiciliées à Villorsonnens et CHF 200.00 pour les personnes de l’extérieur. Il s’agit d’un tarif de location de la cabane, pas d’un tarif de la place de jeux.","research.remaining[0]":"Il n’est pas indiqué si la place de jeux peut être utilisée sans louer la cabane ; l’interdiction hivernale concerne la cabane, et les règles pour la place de jeux ne sont pas définies.","research.remaining[1]":"La place de jeux de la cabane est-elle ouverte aux familles en hiver ?","research.remaining[2]":"Y a-t-il des toilettes ou une table à langer pour les visiteurs à la cabane ?","research.remaining[3]":"La page de la commune écrit le village de la cabane « Villagiroud » dans son propre texte, mais « Villargiroud » dans l’adresse postale de la commune ; quelle orthographe les familles doivent-elles utiliser pour la cabane ?","research.remaining[4]":"Quelle est l’adresse exacte de la cabane pour les visiteurs ?","research.remaining[5]":"Les familles peuvent-elles utiliser la place de jeux sans louer la cabane, et existe-t-il des règles pour celle-ci ? Le document des conditions de location lié par la commune n’a pas pu être lu.","research.remaining[6]":"La place de jeux est-elle à l’extérieur, et existe-t-il un chemin adapté aux poussettes pour y accéder ?","contacts[0].name":"Commune de Villorsonnens","sources[0].label":"Commune : place de jeux près de la cabane de la forêt et conditions de location"}},
"vita-chatel":{"rev":"debf319c99809271fdd716c9f3701d99b81c2776f26d47c146d6343fcb3aeeba","strings":{"name":"Parcours Vita · forêt et mouvement","intro":"Une boucle gratuite en forêt avec des stations de mouvement.","parentDetails":"Un parent accompagne l’enfant sur la boucle en forêt.","age":"Promenade en famille ; choisir les exercices adaptés à l’âge","schedule":"Toute l’année, de jour et par temps adapté","price":"Gratuit","address":"Départ en face du camping Le Bivouac, 1618 Châtel-St-Denis","notes[0]":"Boucle en forêt d’environ 50 minutes avec des stations de mouvement pour les familles, conçues comme un jeu ; dénivelé de 68 m.","notes[1]":"Le départ se trouve en face du camping Le Bivouac, avec environ 50 places de parc à proximité. Le numéro exact de la rue n’est pas indiqué.","notes[2]":"Le parcours n’est pas accessible aux personnes à mobilité réduite. Les familles choisissent elles-mêmes les exercices ; les stations ne sont pas conçues pour un groupe d’enfants d’âge préscolaire encadré.","practical.indoor.text":"Parcours en forêt","practical.access.text":"Le parcours n’est pas adapté aux personnes à mobilité réduite","practical.parking.text":"Environ 50 places près du départ","practical.duration.text":"Durée indicative : environ 50 minutes","research.findings[0].field":"Boucle en forêt","research.findings[0].text":"La boucle gratuite, ouverte toute l’année et d’environ 50 minutes, commence en face du camping Le Bivouac. Le parcours n’est pas accessible aux personnes à mobilité réduite.","research.remaining[0]":"L’adresse exacte du départ et l’adéquation des différents exercices pour les jeunes enfants ne sont pas publiées.","contacts[0].name":"Les Paccots Tourisme","sources[0].label":"Accès toute l’année, prix, départ et parcours"}},
"vitromusee-romont":{"rev":"76a635e968c9d119dff63355118817777247181b2e16b1dbf66c7c64ed4b0bcf","strings":{"name":"Vitromusée · espace pour enfants","intro":"Musée du verre avec un espace créatif pour enfants.","parentDetails":"Visite en famille ; un adulte accompagne l’enfant.","age":"Enfants jusqu’à 16 ans avec un adulte : gratuit ; jeu-parcours pour les enfants qui savent lire","schedule":"mar.–dim. 10:00–17:00 jusqu’au 31.10 ; dès novembre 11:00–17:00","price":"Adulte CHF 15 ; enfant jusqu’à 16 ans avec un adulte : gratuit","address":"Château de Romont, 1680 Romont","notes[0]":"Le musée dispose d’un espace créatif séparé. Le parcours de questions à travers les salles est conçu pour les enfants qui savent lire ; il peut ne pas convenir aux plus jeunes.","notes[1]":"Les ateliers thématiques et les programmes de l’après-midi ont leurs propres dates et conditions ; un billet de musée n’est pas la même chose qu’une inscription à un atelier.","notes[2]":"Avant la sortie, vérifiez si les escaliers du château sont praticables avec une poussette.","practical.indoor.text":"Exposition dans le château","practical.playArea.text":"Espace créatif séparé pour les enfants","practical.warnings[0]":"Le jeu-parcours imprimé à travers les salles est conçu pour les enfants qui savent lire ; les ateliers sont payants et font l’objet d’une inscription séparée","research.findings[0].field":"Pour les enfants","research.findings[0].text":"Le musée dispose d’un espace créatif pour enfants ; le jeu-parcours à travers les salles est conçu pour les enfants qui savent déjà lire.","research.findings[1].field":"Entrée","research.findings[1].text":"Enfants jusqu’à 16 ans avec un adulte : gratuit ; billet adulte CHF 15.","research.remaining[0]":"Vérifier l’accès au château avec une poussette et l’âge requis pour les prochains ateliers.","contacts[0].name":"Vitromusée","sources[0].label":"Espace pour enfants et jeu-parcours","sources[1].label":"Entrée, adresse et horaires d’ouverture"}},
